arguments.query:
query VideoRunContext {
 games(first: 100, offset: 0) { nodes { id name slug status } pageInfo { total first offset hasMore nextOffset } }
 videos(first: 100, offset: 0) { nodes { id title slug status duration publishedAt game { id name slug } playlists { id title slug } } pageInfo { total first offset hasMore nextOffset } }
 collections(first: 100, offset: 0) { nodes { id title slug game { id name slug } } pageInfo { total first offset hasMore nextOffset } }
}
